// === Unstop Competitions API ===
// Same public search endpoint as 05-unstop-hackathons but tuned for the
// `competitions` surface — case competitions, business plan contests,
// design competitions, etc. Maps cleanly to our `case_competition`
// category since that is what dominates the response.
//
// IMPORTANT: the endpoint sometimes returns mixed types (a hackathon may
// appear when ?opportunity=competitions is queried). We filter by
// per-item type/seo_url to keep this workflow strictly competitions —
// hackathons are already covered by workflow 05.

function stripHtml(s) {
  if (!s) return null;
  return String(s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

let data;
try {
  data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://unstop.com/api/public/opportunity/search-result?opportunity=competitions&per_page=20&oppstatus=open',
    json: true,
    headers: { Accept: 'application/json' },
  });
} catch (e) {
  throw new Error('Unstop competitions fetch failed: ' + ((e && e.message) || e));
}

const rawItems = (data && data.data && Array.isArray(data.data.data)) ? data.data.data : [];
// Keep only true competitions; the API leaks hackathons into this surface.
const items = rawItems.filter((h) => {
  const type = String(h.type || '').toLowerCase();
  const seo = String(h.seo_url || '').toLowerCase();
  if (type === 'competitions') return true;
  if (seo.includes('/competitions/')) return true;
  return false;
});
if (items.length === 0) {
  throw new Error('Unstop returned 0 competitions after filtering');
}

function extractTags(h) {
  const tags = new Set();
  if (Array.isArray(h.required_skills)) {
    for (const s of h.required_skills) {
      const name = (s && (s.name || s.title)) || (typeof s === 'string' ? s : null);
      if (name) tags.add(String(name).toLowerCase());
    }
  }
  if (Array.isArray(h.filters)) {
    for (const f of h.filters) {
      const name = (f && (f.name || f.title)) || (typeof f === 'string' ? f : null);
      if (name) tags.add(String(name).toLowerCase());
    }
  }
  return Array.from(tags).slice(0, 6);
}

function extractLocation(h) {
  if (h.address_with_country_logo) {
    const a = h.address_with_country_logo;
    return [a.city, a.state, a.country].filter(Boolean).join(', ') || 'India';
  }
  if (typeof h.location === 'string') return h.location;
  return 'India';
}

function extractCompensation(h) {
  if (h.prize_money) return stripHtml(String(h.prize_money));
  if (Array.isArray(h.prizes) && h.prizes.length) {
    const first = h.prizes[0];
    if (first && first.amount) return stripHtml(String(first.amount));
  }
  return null;
}

function extractEligibility(h) {
  if (h.regnRequirements) {
    const r = h.regnRequirements;
    const parts = [];
    if (r.team_size_min || r.team_size_max) {
      parts.push(`Team size: ${r.team_size_min || 1}-${r.team_size_max || 'any'}`);
    }
    if (r.eligibility) parts.push(stripHtml(String(r.eligibility)));
    return parts.length ? parts.join('. ') : null;
  }
  return null;
}

const out = [];
for (const h of items) {
  const orgName = stripHtml((h.organisation && h.organisation.name) || 'Unstop');
  const cleanDesc = stripHtml(h.description);
  const summary = cleanDesc
    ? (cleanDesc.length > 280 ? cleanDesc.slice(0, 277) + '...' : cleanDesc)
    : `Competition by ${orgName}`;

  const opportunity = {
    title: stripHtml(h.title) || 'Untitled',
    organization: orgName,
    category: 'case_competition',
    description: cleanDesc,
    summary: summary,
    tags: extractTags(h),
    deadline: h.end_date || null,
    eligibility: extractEligibility(h),
    location: extractLocation(h),
    compensation: extractCompensation(h),
    is_remote: false,
    apply_url: h.seo_url,
    difficulty: null,
    estimated_value_score: null,
    extraction_confidence: 0.9,
  };

  out.push({ json: { opportunity, source_url: h.seo_url } });
}

return out;
